// Des: Tests for M13: owner sessions, profile reuse, caps, login wall
// Flo: mock cookie site > account fetches through a persistent profile > assert reuse, stop on wall, day cap, no vendor, no path in logs
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test
// ===================================================================
const std = @import("std"); const rigz = @import("te-brow-rig.zig"); const acct = @import("ru-acct-guar.zig"); const rend = @import("nt-brow-rend.zig"); const cfgz = @import("cf-conf-load.zig"); const sqli = @import("st-stor-sqli.zig");
const allo = std.testing.allocator;
fn logi() cfgz.Conf { var conf: cfgz.Conf = .{}; conf.logi_mode_enab = true; conf.rate_host_seco = 0; return conf; }
fn has(rig: *rigz.Rig, path: []const u8, needle: []const u8) !bool { const rec = (try rig.reco(path)) orelse return false; return std.mem.indexOf(u8, rec.body, needle) != null; }
test "saved profile is reused: login once, later run (browser restarted) reads the gated page" { var rig: rigz.Rig = undefined; try rig.up(logi()); defer rig.down(); try rig.skipNo(); rig.lad.acct = "owner"; _ = try rig.go("/login"); rig.rnd.reset(); const out = try rig.go("/acct"); try std.testing.expectEqualStrings("brow", out.vend); try std.testing.expect(try has(&rig, "/acct", "Account dashboard for owner")); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); }
test "no session: login wall stops the run, never retried, no vendor call" { var rig: rigz.Rig = undefined; try rig.up(logi()); defer rig.down(); try rig.skipNo(); rig.lad.acct = "owner"; try std.testing.expectError(error.LoginWall, rig.go("/acct")); const rn = rig.rnd.rnds; try std.testing.expectError(error.LoginWall, rig.go("/acct")); try std.testing.expectEqual(rn, rig.rnd.rnds); try std.testing.expectEqual(@as(usize, 0), rig.vmk.calls.items.len); try acct.acctClear(&rig.dbzz, "owner"); _ = try rig.go("/login"); const out = try rig.go("/acct"); try std.testing.expectEqualStrings("new", out.stat); }
test "expired session mid-run stops and alerts through the wall flag" { var rig: rigz.Rig = undefined; try rig.up(logi()); defer rig.down(); try rig.skipNo(); rig.lad.acct = "owner"; _ = try rig.go("/login"); _ = try rig.go("/acct"); try acct.acctWall(&rig.dbzz, "owner", 1); try std.testing.expectError(error.LoginWall, rig.go("/acct?n=2")); }
test "daily page cap halts the account" { var conf = logi(); conf.acct_page_maxz = 2; var rig: rigz.Rig = undefined; try rig.up(conf); defer rig.down(); try rig.skipNo(); rig.lad.acct = "owner"; _ = try rig.go("/login"); _ = try rig.go("/acct"); const rn = rig.rnd.rnds; try std.testing.expectError(error.DayCap, rig.go("/acct?n=3")); try std.testing.expectEqual(rn, rig.rnd.rnds); }
test "off unless logi_mode_enab and brow_enab" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); rig.lad.acct = "owner"; try std.testing.expectError(error.NotConfigured, rig.go("/acct")); var rig2: rigz.Rig = undefined; try rig2.up(logi()); defer rig2.down(); rig2.lad.acct = "owner"; rig2.lad.sess = null; try std.testing.expectError(error.NoBrowser, rig2.go("/acct")); }
test "one account = one profile: another account does not see the session" { var rig: rigz.Rig = undefined; try rig.up(logi()); defer rig.down(); try rig.skipNo(); rig.lad.acct = "owner"; _ = try rig.go("/login"); const other = try std.fs.path.join(allo, &.{ rig.profd, "other" }); defer allo.free(other); var rnd2 = try rend.rndrInit(allo, std.testing.io, logi(), other); defer rnd2.deinit(); rnd2.conf.brow_enab = true; rig.lad.sess = &rnd2; rig.lad.acct = "other"; try std.testing.expectError(error.LoginWall, rig.go("/acct")); rig.lad.sess = &rig.rnd; }
test "profile path never reaches the logs" { var rig: rigz.Rig = undefined; try rig.up(logi()); defer rig.down(); try rig.skipNo(); rig.lad.acct = "owner"; _ = rig.go("/acct") catch {}; var stmt = try rig.dbzz.prep("SELECT group_concat(note || ' ' || urlz || ' ' || vend, ' ') FROM logz;"); defer stmt.fini(); _ = try stmt.step(); const all = stmt.colText(0); try std.testing.expect(std.mem.indexOf(u8, all, "prof") == null); try std.testing.expect(std.mem.indexOf(u8, all, ".zig-cache") == null); }
test "spacing: accounts wait last + 3x rate_host_seco" { var rig: rigz.Rig = undefined; try rig.up(.{}); defer rig.down(); const t1 = try acct.acctTake(&rig.dbzz, "a", 1_000_000_000, 10, 3000); try std.testing.expectEqual(@as(u64, 0), t1.wait); const t2 = try acct.acctTake(&rig.dbzz, "a", 1_000_000_500, 10, 3000); try std.testing.expectEqual(@as(u64, 2500), t2.wait); const t3 = try acct.acctTake(&rig.dbzz, "a", 1_000_000_000 + 86_400_000, 10, 3000); try std.testing.expectEqual(@as(u64, 0), t3.wait); try std.testing.expectEqual(@as(i64, 1), try acct.acctUsed(&rig.dbzz, "a", 1_000_000_000 + 86_400_000)); }
